'use strict';
/* InkForge app shell: data layer client, migrations, router, tooltips, backup. */
const APP_BUILD = 542;
const GOOGLE_ON = false;   // Google Drive workspaces and Calendar sync: switched off and hidden for now (the code stays; true brings them back)   // the build number shown around the app; bump it with sw.js

/* ---------- Database (talks to lib/db-worker.js) ---------- */
const DB = (() => {
  const worker = new Worker('lib/db-worker.js');
  const pending = new Map();
  let seq = 0;
  worker.onmessage = (e) => {
    const { id, ok, res, error } = e.data;
    const p = pending.get(id); pending.delete(id);
    ok ? p.resolve(res) : p.reject(new Error(error));
  };
  const call = (op, args, transfer) => new Promise((resolve, reject) => {
    const id = ++seq; pending.set(id, { resolve, reject });
    worker.postMessage({ id, op, args }, transfer || []);
  });
  return {
    info: () => call('info'),
    all: async (sql, params) => (await call('exec', { sql, params })).rows,
    one: async (sql, params) => (await call('exec', { sql, params })).rows[0],
    run: (sql, params) => Cloud.guard(sql) || call('exec', { sql, params }).finally(() => Snapshot.soon()),
    tx: (items) => Cloud.guard(items.map(i => i.sql).join(';')) || call('tx', { items }).finally(() => Snapshot.soon()),
    open: (path) => call('open', { path }),
    drop: (path) => call('drop', { path }),
    exportBytes: async (path) => (await call('export', { path })).bytes,
    importBytes: (bytes) => call('import', { bytes }, [bytes.buffer]).finally(() => Snapshot.soon()),
    peek: async (bytes) => (await call('peek', { bytes }, [bytes.buffer])).tables,
    release: () => worker.terminate()   // lets go of the database (and its lock) for good: only when another tab takes over
  };
})();

/* Safety net: a copy of the database kept as a plain OPFS file, outside the SQLite storage pool.
   Written a few seconds after changes and when the app goes to the background. If the app ever
   starts on an empty database while a snapshot exists, boot restores it. An empty database is
   never snapshotted, so a good copy can't be overwritten by a blank one. */
const Snapshot = {
  ready: false, _t: null,
  async handle(create) {
    const d = await (await navigator.storage.getDirectory()).getDirectoryHandle('snapshots', { create: true });
    return d.getFileHandle(WS.snapName(WS.cur), { create });
  },
  soon() { if (!this.ready) return; clearTimeout(this._t); this._t = setTimeout(() => this.save(), 4000); },
  async save() {
    clearTimeout(this._t);
    if (!this.ready) return;
    try {
      if (!(await hasData())) return;
      const bytes = await DB.exportBytes();
      const w = await (await this.handle(true)).createWritable();
      await w.write(bytes); await w.close();
      if (WS.cur?.cloud) Cloud.soon();
    } catch (e) { console.warn('Snapshot failed:', e); }
  },
  async load() {
    try { const f = await (await this.handle(false)).getFile(); return f.size ? new Uint8Array(await f.arrayBuffer()) : null; }
    catch { return null; }
  }
};
document.addEventListener('visibilitychange', () => { if (document.hidden) Snapshot.save(); });

/* Phone numbers are kept in international form (+27 82 123 4567) so WhatsApp and links work.
   A local number starting with 0 is converted with the country code from Settings. */
const countryCode = () => (Settings.get('country_code') || '').replace(/\D/g, '');
function intlPhone(v) {
  const t = String(v || '').trim(); if (!t) return '';
  if (t.startsWith('+')) return t;
  if (t.startsWith('00')) return '+' + t.slice(2);
  if (/^0\d/.test(t) && countryCode()) return `+${countryCode()} ${t.slice(1)}`;
  return null;                                                          // can't tell the country
}
const phoneHint = () => countryCode() ? `+${countryCode()} 82 123 4567` : '+ country code, then the number';
const phoneBad = () => countryCode() ? 'Check the number; it needs to start with + and the country code.'
  : 'Start the number with + and the country code (e.g. +27 82 123 4567), or set your country code in Settings.';
document.addEventListener('focusin', (e) => { if (e.target.matches?.('input[type=tel]') && !e.target.placeholder) e.target.placeholder = phoneHint(); });
document.addEventListener('focusout', (e) => {
  const i = e.target; if (!i.matches?.('input[type=tel]') || i.dataset.raw != null) return;
  const v = intlPhone(i.value);
  if (v === null) { i.classList.add('bad'); toast(phoneBad()); return; }
  i.classList.remove('bad');
  if (v !== i.value.trim()) { i.value = v; i.dispatchEvent(new Event('change', { bubbles: true })); }
}, true);

// Combo boxes: browsers filter a datalist by the current value, so a filled box only offers its own
// value. Park the value as the placeholder while the box is opened, and put it back if nothing new is picked.
document.addEventListener('pointerdown', (e) => {
  const i = e.target.closest?.('input[list]'); if (!i || !i.value) return;
  i.dataset.prev = i.value; i.dataset.ph = i.placeholder; i.placeholder = i.value; i.value = '';
}, true);
document.addEventListener('focusout', (e) => {
  const i = e.target; if (!i.matches?.('input[list]') || i.dataset.prev == null) return;
  if (!i.value) i.value = i.dataset.prev;
  i.placeholder = i.dataset.ph || ''; delete i.dataset.prev; delete i.dataset.ph;
}, true);

/* ---------- Workspaces ----------
   Each workspace (e.g. one per artist) is its own database file, media folder and snapshot.
   The list lives in OPFS as workspaces.json (not localStorage). The original single database
   is the workspace "main", keeping its old file names, so existing data needs no migration. */
const WS = {
  list: [], last: null, auto: false, cur: null, gid: '', device: null,
  dbPath: (w) => w.id === 'main' ? '/inkforge.db' : `/ws-${w.id}.db`,
  mediaName: (w) => w.id === 'main' ? 'media' : `media-${w.id}`,
  snapName: (w) => w.id === 'main' ? 'latest.sqlite' : `ws-${w.id}.sqlite`,
  async file(create) { return (await navigator.storage.getDirectory()).getFileHandle('workspaces.json', { create }); },
  async load() {
    try { Object.assign(this, JSON.parse(await (await (await this.file(false)).getFile()).text())); } catch {}
    if (!this.list.length) this.list = [{ id: 'main', name: 'My workspace', created: new Date().toISOString(), opened: null }];
  },
  async save() {
    const w = await (await this.file(true)).createWritable();
    await w.write(JSON.stringify({ list: this.list, last: this.last, auto: this.auto, fs: this.fs, gid: this.gid, device: this.device })); await w.close();
  },
  get: (id) => WS.list.find(w => w.id === id),
  async create(name) {
    const w = { id: Date.now().toString(36), name, created: new Date().toISOString(), opened: null };
    this.list.push(w); await this.save(); return w;
  },
  // Opening switches the database, media folder and snapshot to this workspace.
  async open(w) {
    this.cur = w;
    await DB.open(this.dbPath(w)); setTimeout(() => { try { Notif.plan(); } catch {} }, 2000);
    w.opened = new Date().toISOString(); this.last = w.id; await this.save();
  },
  async remove(w) {
    await DB.drop(this.dbPath(w));
    const root = await navigator.storage.getDirectory();
    try { await root.removeEntry(this.mediaName(w), { recursive: true }); } catch {}
    try { await (await root.getDirectoryHandle('snapshots')).removeEntry(this.snapName(w)); } catch {}
    this.list = this.list.filter(x => x !== w); if (this.last === w.id) this.last = null;
    await this.save();
  },
  // Switching reloads the page so no state from the previous workspace can leak into the next.
  switchTo(id) {
    try { sessionStorage.setItem('ws-open', id || ''); sessionStorage.setItem('ws-start', id ? '' : '1'); } catch {}
    location.hash = 'home'; location.reload();
  }
};
// A database "has data" once migrations have created app_meta (sqlite_sequence alone doesn't count).
const hasData = async () => !!(await DB.one(`SELECT 1 AS x FROM sqlite_master WHERE type = 'table' AND name = 'app_meta'`));

/* Append-only. Never edit a past entry; add a new one. SCHEMA_VERSION = MIGRATIONS.length.
   Adding a table? Also add it to MERGE_TABLES (backup merge). Full backups include every table
   and media file automatically; merge needs to know which section a table belongs to. */
const MIGRATIONS = [
  // v1: meta + settings
  `CREATE TABLE IF NOT EXISTS app_meta (key TEXT PRIMARY KEY, value TEXT);
   CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);`,
  // v2: clients. photo_ref is a filename in the OPFS media folder, never bytes.
  `CREATE TABLE clients (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     first_name TEXT NOT NULL DEFAULT '', last_name TEXT NOT NULL DEFAULT '',
     phone TEXT, email TEXT, instagram TEXT, dob TEXT, pronouns TEXT,
     medical TEXT, notes TEXT, tags TEXT, photo_ref TEXT,
     created_at TEXT NOT NULL DEFAULT (datetime('now')),
     updated_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE INDEX idx_clients_name ON clients (last_name COLLATE NOCASE, first_name COLLATE NOCASE);`,
  // v3: bookings. start_at is local time 'YYYY-MM-DDTHH:MM'. gcal_* reserved for Google sync.
  `CREATE TABLE bookings (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     client_id INTEGER REFERENCES clients(id) ON DELETE SET NULL,
     start_at TEXT NOT NULL, duration_min INTEGER NOT NULL DEFAULT 120,
     description TEXT, placement TEXT, size TEXT,
     quote REAL, deposit REAL, deposit_paid INTEGER NOT NULL DEFAULT 0,
     notes TEXT, gcal_id TEXT, gcal_updated TEXT,
     created_at TEXT NOT NULL DEFAULT (datetime('now')),
     updated_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE INDEX idx_bookings_start ON bookings (start_at);
   CREATE INDEX idx_bookings_client ON bookings (client_id);
   CREATE TABLE booking_photos (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     booking_id INTEGER NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
     photo_ref TEXT NOT NULL, sort INTEGER NOT NULL DEFAULT 0);
   CREATE INDEX idx_bphotos_booking ON booking_photos (booking_id);`,
  // v4: Google Calendar sync. gcal_synced_at = local updated_at value last pushed/pulled.
  `ALTER TABLE bookings ADD COLUMN gcal_synced_at TEXT;
   CREATE TABLE gcal_deletes (gcal_id TEXT PRIMARY KEY);
   CREATE TABLE gcal_busy (start_at TEXT NOT NULL, end_at TEXT NOT NULL);
   CREATE INDEX idx_gcal_busy ON gcal_busy (start_at);`,
  // v5: forms. blocks = JSON array of {t: 'h'|'p'|'check'|'field', text}. Signed forms keep a
  // frozen copy of the blocks so later template edits never change what a client signed.
  `CREATE TABLE form_templates (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     kind TEXT NOT NULL CHECK (kind IN ('consent', 'aftercare')),
     title TEXT NOT NULL, blocks TEXT NOT NULL DEFAULT '[]',
     updated_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE TABLE signed_forms (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     client_id INTEGER REFERENCES clients(id) ON DELETE SET NULL,
     booking_id INTEGER REFERENCES bookings(id) ON DELETE SET NULL,
     template_id INTEGER REFERENCES form_templates(id) ON DELETE SET NULL,
     kind TEXT NOT NULL, title TEXT NOT NULL, client_name TEXT,
     blocks TEXT NOT NULL, answers TEXT NOT NULL DEFAULT '{}',
     signature_ref TEXT, signed_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE INDEX idx_signed_client ON signed_forms (client_id);`,
  // v6: portfolio. Each photo has a full-size ref and a small grid thumbnail ref.
  `CREATE TABLE portfolio_items (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     kind TEXT NOT NULL CHECK (kind IN ('tattoo', 'art', 'flash')),
     title TEXT, description TEXT, placement TEXT, tags TEXT,
     client_id INTEGER REFERENCES clients(id) ON DELETE SET NULL,
     booking_id INTEGER REFERENCES bookings(id) ON DELETE SET NULL,
     made_on TEXT, price REAL, claimed INTEGER NOT NULL DEFAULT 0,
     favourite INTEGER NOT NULL DEFAULT 0,
     created_at TEXT NOT NULL DEFAULT (datetime('now')),
     updated_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE INDEX idx_pf_kind ON portfolio_items (kind, made_on);
   CREATE INDEX idx_pf_client ON portfolio_items (client_id);
   CREATE TABLE portfolio_photos (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     item_id INTEGER NOT NULL REFERENCES portfolio_items(id) ON DELETE CASCADE,
     photo_ref TEXT NOT NULL, thumb_ref TEXT NOT NULL, label TEXT, sort INTEGER NOT NULL DEFAULT 0);
   CREATE INDEX idx_pf_photos ON portfolio_photos (item_id);`,
  // v7: inventory, stock takes, rule book.
  `CREATE TABLE inventory_items (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     name TEXT NOT NULL, category TEXT, unit TEXT,
     qty REAL NOT NULL DEFAULT 0, min_qty REAL NOT NULL DEFAULT 0,
     supplier TEXT, cost REAL, notes TEXT,
     updated_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE TABLE stock_takes (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     taken_at TEXT NOT NULL DEFAULT (datetime('now')), notes TEXT);
   CREATE TABLE stock_take_lines (
     take_id INTEGER NOT NULL REFERENCES stock_takes(id) ON DELETE CASCADE,
     item_id INTEGER REFERENCES inventory_items(id) ON DELETE SET NULL,
     item_name TEXT NOT NULL, expected REAL, counted REAL NOT NULL);
   CREATE TABLE rules (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     title TEXT NOT NULL, body TEXT, sort INTEGER NOT NULL DEFAULT 0);`,
  // v8: booking type (see BOOKING_KINDS). Existing bookings are tattoo sessions.
  `ALTER TABLE bookings ADD COLUMN kind TEXT NOT NULL DEFAULT 'tattoo';`,
  // v9: finishing a tattoo. completed + what was paid and how long it took (feeds Stats), the
  // follow-up booking it spawned (followup_of on the follow-up), and the promotion on its receipt.
  `ALTER TABLE bookings ADD COLUMN completed INTEGER NOT NULL DEFAULT 0;
   ALTER TABLE bookings ADD COLUMN completed_at TEXT;
   ALTER TABLE bookings ADD COLUMN paid REAL;
   ALTER TABLE bookings ADD COLUMN time_min INTEGER;
   ALTER TABLE bookings ADD COLUMN pay_method TEXT;
   ALTER TABLE bookings ADD COLUMN followup_of INTEGER REFERENCES bookings(id) ON DELETE SET NULL;
   ALTER TABLE bookings ADD COLUMN promo_kind TEXT;
   ALTER TABLE bookings ADD COLUMN promo_value REAL;
   ALTER TABLE bookings ADD COLUMN promo_until TEXT;
   CREATE INDEX idx_bookings_done ON bookings (completed, start_at);`,
  // v10: phonebook categories, so suppliers and services live apart from clients.
  `ALTER TABLE clients ADD COLUMN category TEXT NOT NULL DEFAULT 'Client';
   CREATE INDEX idx_clients_cat ON clients (category);`,
  // v11: rule book categories, e.g. client rules apart from staff rules.
  `ALTER TABLE rules ADD COLUMN category TEXT NOT NULL DEFAULT 'Client rules';`,
  // v12: inactive stock items are kept but left out of counts, stock takes, alerts and prints.
  `ALTER TABLE inventory_items ADD COLUMN active INTEGER NOT NULL DEFAULT 1;`,
  // v13: type of work on a booking (new, cover, scar, fix), so receipts can carry the right advice.
  `ALTER TABLE bookings ADD COLUMN job TEXT;`,
  // v14: saved quotes. data = the wizard answers, cfg = the Calibrate values it was priced with.
  `CREATE TABLE quotes (
     id INTEGER PRIMARY KEY,
     client_name TEXT,
     summary TEXT,
     data TEXT NOT NULL,
     cfg TEXT NOT NULL,
     total REAL,
     hours REAL,
     design_ref TEXT,
     booking_id INTEGER REFERENCES bookings(id) ON DELETE SET NULL,
     completed INTEGER NOT NULL DEFAULT 0,
     created_at TEXT NOT NULL DEFAULT (datetime('now')),
     updated_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE INDEX idx_quotes_booking ON quotes (booking_id);`,
  // v15: the client's reply from a quote link (option, day, start time, contact), as JSON.
  `ALTER TABLE quotes ADD COLUMN reply TEXT;`,
  // v16: a booking can carry a name and number without saving the person as a client.
  `ALTER TABLE bookings ADD COLUMN guest_name TEXT;
   ALTER TABLE bookings ADD COLUMN guest_phone TEXT;`,
  // v17: background behind a portfolio picture ('' = as is / transparent, 'white', 'black'), on screen and in print.
  `ALTER TABLE portfolio_items ADD COLUMN bg TEXT;`,
  // v18: design studio (vouchers, cards, flyers, posts). doc = the design as JSON; its pictures are listed
  // in design_assets so backups and merges carry them and Media.release never removes one still in use.
  `CREATE TABLE designs (
     id INTEGER PRIMARY KEY,
     name TEXT NOT NULL,
     kind TEXT NOT NULL,
     doc TEXT NOT NULL,
     thumb_ref TEXT,
     created_at TEXT NOT NULL DEFAULT (datetime('now')),
     updated_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE TABLE design_assets (
     design_id INTEGER NOT NULL REFERENCES designs(id) ON DELETE CASCADE,
     ref TEXT NOT NULL);
   CREATE INDEX idx_design_assets ON design_assets (design_id);`,
  // v19: references, pictures collected for ideas (not your own work), kept apart from the portfolio.
  // Stored converted (PNG when see-through, otherwise JPG) at the size chosen when added.
  `CREATE TABLE ref_images (
     id INTEGER PRIMARY KEY,
     title TEXT,
     category TEXT NOT NULL DEFAULT 'Inspiration',
     tags TEXT,
     photo_ref TEXT NOT NULL,
     thumb_ref TEXT NOT NULL,
     w INTEGER, h INTEGER,
     created_at TEXT NOT NULL DEFAULT (datetime('now')),
     updated_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE INDEX idx_ref_cat ON ref_images (category);`,
  // inventory: how far the + and - buttons move the stock (1 = whole numbers, or 0.5, 0.25, 0.1)
  `ALTER TABLE inventory_items ADD COLUMN step REAL NOT NULL DEFAULT 1;`,
  // assets: vector stickers and shapes kept as SVG files, by category. `layers` holds the design studio's own
  // copy of the shapes (when saved from a design) so they come back editable.
  `CREATE TABLE assets (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     name TEXT, category TEXT NOT NULL DEFAULT 'Shapes', svg_ref TEXT NOT NULL, layers TEXT, w REAL, h REAL,
     created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE INDEX idx_assets_cat ON assets (category);`,
  // stencils kept in the portfolio: the picture they were made from (as cropped and turned), the stencil, a small
  // copy for the grid, the print width and the stencil settings (to open it again in the stencil maker)
  `CREATE TABLE stencils (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     name TEXT, src_ref TEXT NOT NULL, stencil_ref TEXT NOT NULL, thumb_ref TEXT, w INTEGER, h INTEGER, cm REAL, params TEXT,
     created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));`,
  // tattoo simulator (experimental, see tattoo.js): one picture per fixed layer, the page in cm and the skin tone
  `CREATE TABLE tattoo_pieces (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     name TEXT, w_cm REAL NOT NULL, h_cm REAL NOT NULL, skin TEXT, meta TEXT,
     stencil_ref TEXT, line_ref TEXT, shadow_ref TEXT, mid_ref TEXT, light_ref TEXT, high_ref TEXT, thumb_ref TEXT,
     created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));`,
  // tattoo simulator: the worked skin (trauma map) and blowouts
  `ALTER TABLE tattoo_pieces ADD COLUMN skin_ref TEXT;
   ALTER TABLE tattoo_pieces ADD COLUMN blow_ref TEXT;`,
  // saved reels: the edit (clips, cards, transitions, music settings, style) as JSON; its photos, videos and song are
  // media files named inside doc
  `CREATE TABLE reels (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     name TEXT, doc TEXT, thumb_ref TEXT,
     created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));`,
  // tattoo simulator: the skin marker layer (freehand drawn on the skin), beside the stencil
  `ALTER TABLE tattoo_pieces ADD COLUMN marker_ref TEXT;`,
  // forms made in the designer: a completed form is kept as flattened page pictures
  `CREATE TABLE signed_form_pages (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     form_id INTEGER NOT NULL REFERENCES signed_forms(id) ON DELETE CASCADE,
     ref TEXT NOT NULL, sort INTEGER NOT NULL DEFAULT 0);
   CREATE INDEX idx_signed_pages ON signed_form_pages (form_id);`,
  // imported bookings: src_uid = the booking's id where it came from, src_ws = that workspace; an optional tag and colour;
  // ghost = shown for reference only (not counted, not editable, not shared to Google)
  `ALTER TABLE bookings ADD COLUMN src_uid TEXT;
   ALTER TABLE bookings ADD COLUMN src_ws TEXT;
   ALTER TABLE bookings ADD COLUMN tag TEXT;
   ALTER TABLE bookings ADD COLUMN tag_color TEXT;
   ALTER TABLE bookings ADD COLUMN ghost INTEGER NOT NULL DEFAULT 0;
   CREATE INDEX idx_bookings_src ON bookings (src_uid);`,
  // imported clients: src_uid = the client's id where it came from, src_ws = that workspace; tag and colour say whose client
  `ALTER TABLE clients ADD COLUMN src_uid TEXT;
   ALTER TABLE clients ADD COLUMN src_ws TEXT;
   ALTER TABLE clients ADD COLUMN tag TEXT;
   ALTER TABLE clients ADD COLUMN tag_color TEXT;
   CREATE INDEX idx_clients_src ON clients (src_uid);`,
  // imported stock items: where they came from, and a tag and colour saying whose stock
  `ALTER TABLE inventory_items ADD COLUMN src_uid TEXT;
   ALTER TABLE inventory_items ADD COLUMN src_ws TEXT;
   ALTER TABLE inventory_items ADD COLUMN tag TEXT;
   ALTER TABLE inventory_items ADD COLUMN tag_color TEXT;
   CREATE INDEX idx_inventory_src ON inventory_items (src_uid);`,
  // stock items: pack = how many come in a full pack (counted in packs and loose ones), sort = your own count order
  `ALTER TABLE inventory_items ADD COLUMN pack INTEGER;
   ALTER TABLE inventory_items ADD COLUMN sort INTEGER;`,
  // a portfolio entry's reel: one video (the media folder's file name), shown with its photos
  `ALTER TABLE portfolio_items ADD COLUMN reel_ref TEXT;`,
  // referrals: the contact who sent them (referred_by), or how else they found you (ref_src: online, advert, other) and a note
  `ALTER TABLE clients ADD COLUMN referred_by INTEGER REFERENCES clients(id) ON DELETE SET NULL;
   ALTER TABLE clients ADD COLUMN ref_src TEXT;
   ALTER TABLE clients ADD COLUMN ref_note TEXT;`,
  // a tattoo's kind of work: '' (new), 'cover' (cover up) or 'fix' (fix up); its photos can be tagged Before and After
  `ALTER TABLE portfolio_items ADD COLUMN job TEXT;`,
  // loyalty rewards: who holds it (client_id), what it is (kind 'pct' or 'amount', value), where it came from (src 'ref' or
  // 'spend', from_client, from_booking), when it runs out, and where it was used; bookings.loy_off = what rewards took off
  `CREATE TABLE loyalty_rewards (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     client_id INTEGER REFERENCES clients(id) ON DELETE SET NULL,
     kind TEXT NOT NULL DEFAULT 'pct', value REAL NOT NULL DEFAULT 0, code TEXT,
     src TEXT, from_client INTEGER REFERENCES clients(id) ON DELETE SET NULL, from_booking INTEGER REFERENCES bookings(id) ON DELETE SET NULL,
     issued_at TEXT NOT NULL DEFAULT (date('now')), expires_at TEXT,
     status TEXT NOT NULL DEFAULT 'open', used_booking INTEGER REFERENCES bookings(id) ON DELETE SET NULL, used_at TEXT,
     passed_from INTEGER REFERENCES clients(id) ON DELETE SET NULL, note TEXT,
     created_at TEXT NOT NULL DEFAULT (datetime('now')));
   CREATE INDEX idx_loy_client ON loyalty_rewards (client_id);
   CREATE INDEX idx_loy_from ON loyalty_rewards (from_booking);
   ALTER TABLE bookings ADD COLUMN loy_off REAL;`,
  // loyalty: a product as the reward (kind 'item': item_id, item_name), a product they can choose instead (alt_id,
  // alt_name), and the tier it was earned at
  `ALTER TABLE loyalty_rewards ADD COLUMN item_id INTEGER;
   ALTER TABLE loyalty_rewards ADD COLUMN item_name TEXT;
   ALTER TABLE loyalty_rewards ADD COLUMN alt_id INTEGER;
   ALTER TABLE loyalty_rewards ADD COLUMN alt_name TEXT;
   ALTER TABLE loyalty_rewards ADD COLUMN tier TEXT;`,
  // loyalty: the program's rules a reward was earned under (JSON: v = that version of the program, stack, maxStack, pass),
  // so changing or switching off the program never changes rewards already out
  `ALTER TABLE loyalty_rewards ADD COLUMN prog TEXT;`,
  // booking reminders: notify_min = how many minutes before the start to remind (NULL = no reminder)
  `ALTER TABLE bookings ADD COLUMN notify_min INTEGER;`,
  // reward sent to the client (date marked); a client who can't earn rewards (kept in the referral tree);
  // cancelled bookings: kept on record but out of stats and free time (by: client, noshow or me; a reason; when)
  `ALTER TABLE loyalty_rewards ADD COLUMN sent_at TEXT;
   ALTER TABLE clients ADD COLUMN loy_off INTEGER NOT NULL DEFAULT 0;
   ALTER TABLE clients ADD COLUMN loy_off_note TEXT;
   ALTER TABLE bookings ADD COLUMN cancelled INTEGER NOT NULL DEFAULT 0;
   ALTER TABLE bookings ADD COLUMN cancel_by TEXT;
   ALTER TABLE bookings ADD COLUMN cancel_reason TEXT;
   ALTER TABLE bookings ADD COLUMN cancelled_at TEXT;`,
  // a deleted reward is archived, not removed: when, why, and what it was before (to restore it)
  `ALTER TABLE loyalty_rewards ADD COLUMN deleted_at TEXT;
   ALTER TABLE loyalty_rewards ADD COLUMN del_reason TEXT;
   ALTER TABLE loyalty_rewards ADD COLUMN del_prev TEXT;`
];
const RULE_CATS = ['Client rules', 'Staff rules'];
const RULES = { cat: 'all' };
const CLIENT_CATS = ['Client', 'Supporter', 'Supplier', 'Service'];   /* Supporter: never tattooed, but sends people your way */
/* Booking types. ink: shows the tattoo fields (placement, size, quote, deposit, references). */
const BOOKING_KINDS = {
  tattoo: { label: 'Tattoo', ink: true }, consult: { label: 'Consultation', ink: true }, touchup: { label: 'Touch-up', ink: true },
  followup: { label: 'Follow-up' }, hold: { label: 'Hold' }, meeting: { label: 'Meeting' }, leave: { label: 'Leave' }, other: { label: 'Other' }
};
// Kinds that can be marked completed (and so count in Stats, get a receipt and a follow-up).
const DONE_KINDS = ['tattoo', 'touchup'];
const PAY_METHODS = ['Cash', 'Card', 'EFT', 'Voucher'];
