    const th = (k, l, cls = '') => `<th data-sk="${k}" class="${cls} ${S.k === k || (k === 'no' && S.k === 'order') ? 'on' : ''}">${l}<i>${S.k === k || (k === 'no' && S.k === 'order') ? (S.dir > 0 ? '↑' : '↓') : ''}</i></th>`;
