  $('#rt-add').onclick = () => { location.hash = 'rule-edit/new'; };
  $('#rt-exp').onclick = () => rxExport(rtTable.shown?.rows);
  $('#rt-imp').onclick = () => rxImport().then(n => { if (n) both(); });
