    if (ph.length) await DB.tx(ph.map((p, j) => ({ sql: 'INSERT INTO portfolio_photos (item_id, photo_ref, thumb_ref, label, sort) VALUES (?, ?, ?, ?, ?)', params: [id, ...p, j] })));
    await reelIn(i.x, id); n++;
