  await xSave(new File([JSON.stringify(out)], `forms-${out.ws.name.replace(/[^\w-]+/g, '_')}-${ymd(new Date())}.inkforms`, { type: 'application/json' }), 'Forms', `Saved ${list.length} form${list.length === 1 ? '' : 's'}.`);
