const NOTE_APPS = [['clients', 'Clients', 'user'], ['book', 'Bookings', 'cal'], ['quote', 'Quick quote', 'quote'], ['quotes', 'Saved quotes', 'saved'], ['inventory', 'Inventory', 'stock'], ['rules', 'Rule book', 'rule'], ['stats', 'Stats', 'stats'], ['stencil', 'Stencil maker', 'stencil'], ['reels', 'Reel maker', 'reel'], ['tattoo', 'Tattoo simulator', 'needle'], ['designs', 'Design studio', 'design'], ['portfolio', 'Portfolio', 'portfolio'], ['forms', 'Forms', 'form'], ['settings', 'Settings', 'settings']];
const NOTE_ICO = { user: '<svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"/><path d="M4 21c1-5 4-7 8-7s7 2 8 7"/></svg>', cal: '<svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>' };
const noteIco = (k) => NOTE_ICO[k] || ICON[k] || ICON.design;
async function noteShortcutPick() {
  const q = async (sql, f) => (await DB.all(sql)).map(f);
  const groups = [['Clients', 'user', await q('SELECT id, first_name, last_name FROM clients ORDER BY last_name COLLATE NOCASE LIMIT 300', c => ['client/' + c.id, fullName(c)])],
    ['Appointments', 'cal', await q(`SELECT b.id, b.start_at, c.first_name, c.last_name FROM bookings b LEFT JOIN clients c ON c.id = b.client_id WHERE b.start_at >= date('now') ORDER BY b.start_at LIMIT 100`, b => ['booking-edit/' + b.id, fmtDay(b.start_at) + (b.first_name ? ' · ' + fullName(b) : '')])],
    ['Designs', 'design', await q(`SELECT id, name FROM designs WHERE kind <> 'note' ORDER BY updated_at DESC LIMIT 200`, r => ['design/' + r.id, r.name])],
    ['Tattoo pieces', 'needle', await q(`SELECT id, name FROM tattoo_pieces WHERE meta IS NULL OR meta NOT LIKE '%"mode":"ch"%' ORDER BY updated_at DESC LIMIT 200`, r => ['tattoo/' + r.id, r.name || 'Piece'])],
    ['Reels', 'reel', await q('SELECT id, name FROM reels ORDER BY updated_at DESC LIMIT 200', r => ['reel/' + r.id, r.name || 'Reel'])],
    ['Portfolio', 'portfolio', await q('SELECT id, title FROM portfolio_items ORDER BY id DESC LIMIT 200', r => ['pf/' + r.id, r.title || 'Untitled'])],
    ['Inventory items', 'stock', await q('SELECT id, name FROM inventory_items ORDER BY name COLLATE NOCASE LIMIT 300', r => ['inv-edit/' + r.id, r.name])],
    ['Rules', 'rule', await q('SELECT id, title FROM rules ORDER BY id LIMIT 200', r => ['rule-edit/' + r.id, r.title])]].filter(g => g[2].length);
  return new Promise((res) => { const o = document.createElement('div'); o.id = 'merge-dlg'; const done = (v) => { o.remove(); res(v); };
    o.innerHTML = `<div class="card dz-pick"><h2>Add a shortcut</h2><div class="lbl">Apps</div><div class="ns-grid">${NOTE_APPS.map(([g, n, k]) => `<button data-sg="${g}" data-sn="${esc(n)}" data-si="${k}">${noteIco(k)}<span>${esc(n)}</span></button>`).join('')}</div>
      ${groups.map(([n, k, it]) => `<div class="lbl" style="margin-top:10px">${esc(n)}</div><div class="ns-list">${it.map(([g, t]) => `<button data-sg="${esc(g)}" data-sn="${esc(t)}" data-si="${k}">${esc(t)}</button>`).join('')}</div>`).join('')}
      <button class="btn" data-x style="width:100%;margin-top:12px">Cancel</button></div>`;
    o.onclick = (e) => { const b = e.target.closest('[data-sg]'); if (b) return done({ go: b.dataset.sg, label: b.dataset.sn, svg: noteIco(b.dataset.si) }); if (e.target.closest('[data-x]')) done(null); };
    document.body.appendChild(o); }); }
// The note as a picture (shortcuts and checklists go over it live), redrawn only when it has changed.
async function noteUrl(r) { const c = noteImg.get(r.id); if (c?.at === r.updated_at) return c.url;
  const cv = await dzCanvas({ ...r.doc, layers: (r.doc.layers || []).filter(l => l.t !== 'shortcut' && l.t !== 'check') }, 460 / r.doc.w), url = URL.createObjectURL(await new Promise(res => cv.toBlob(res, 'image/png')));
  if (c) URL.revokeObjectURL(c.url); noteImg.set(r.id, { at: r.updated_at, url }); return url; }
async function notePin(id, on) { const r = await DB.one('SELECT doc FROM designs WHERE id = ?', [id]); if (!r) return; const doc = JSON.parse(r.doc); doc.note = { links: [], ...doc.note, pin: on };
  await DB.run('UPDATE designs SET doc = ? WHERE id = ?', [JSON.stringify(doc), id]); }
// Links whose client or booking still exists, with today's names.
async function noteLive(links) { const out = [];
  for (const l of links) {
    if (l.type === 'web') { out.push({ url: l.url, label: l.label }); continue; }
    if (l.type === 'client') { const c = await DB.one('SELECT id, first_name, last_name FROM clients WHERE id = ?', [l.id]); if (c) out.push({ go: 'client/' + c.id, label: fullName(c) }); }
    else if (l.type === 'booking') { const b = await DB.one('SELECT id, start_at FROM bookings WHERE id = ?', [l.id]); if (b) out.push({ go: 'booking-edit/' + b.id, label: fmtDay(b.start_at) }); }
    else { const s = NOTE_SECTIONS.find(x => x[0] === l.go); if (s) out.push({ go: s[0], label: s[1] }); } }
  return out; }
async function notesPanel() {
  const rows = await notesRows(), us = await Promise.all(rows.map(r => Media.url(r.thumb_ref)));
  const o = document.createElement('div'); o.id = 'merge-dlg';
  o.innerHTML = `<div class="card"><h2>Sticky notes</h2>${rows.length ? rows.map((r, i) => `<div class="note-row"><img src="${us[i] || ''}" alt=""><b>${esc(r.name)}</b>
      <button class="btn small ${r.doc.note?.pin ? 'primary' : ''}" data-p="${r.id}">${r.doc.note?.pin ? 'Pinned' : 'Hidden'}</button><button class="btn small" data-e="${r.id}">Edit</button><button class="btn small" data-d="${r.id}" aria-label="Delete note" data-tip="Delete this note">Delete</button></div>`).join('') : '<p class="muted">No notes yet.</p>'}
    <div class="row" style="gap:8px;margin-top:12px"><button class="btn" data-x>Close</button><span style="flex:1"></span><button class="btn primary" data-n>+ New note</button></div></div>`;
  o.onclick = async (e) => { const t = e.target, p = t.closest('[data-p]')?.dataset.p, ed = t.closest('[data-e]')?.dataset.e;
    if (t.closest('[data-x]') || t === o) { o.remove(); return notesShow(); }
    if (t.closest('[data-n]')) { o.remove(); return dzNoteNew(); }
    if (ed) { o.remove(); location.hash = 'design/' + ed; return; }
    const del = t.closest('[data-d]')?.dataset.d;
    if (del) { const r = rows.find(x => x.id === +del); if (!await ask(`Delete "${r.name}"?

This can't be undone.`)) return;
      const refs = (await DB.all('SELECT ref FROM design_assets WHERE design_id = ?', [r.id])).map(x => x.ref); await DB.run('DELETE FROM designs WHERE id = ?', [r.id]);
      for (const ref of [r.thumb_ref, ...refs]) await Media.release(ref);
      const P = notePos(); delete P[r.id]; await Settings.set('note_pos', JSON.stringify(P)); const c = noteImg.get(r.id); if (c) { URL.revokeObjectURL(c.url); noteImg.delete(r.id); }
      t.closest('.note-row').remove(); return notesShow(); }
    if (p) { const r = rows.find(x => x.id === +p), on = !r.doc.note?.pin; await notePin(+p, on); r.doc.note = { ...r.doc.note, pin: on }; t.textContent = on ? 'Pinned' : 'Hidden'; t.classList.toggle('primary', on); } };
  document.body.appendChild(o);
}
// Choosing a note's links: sections, a client, an upcoming appointment. Resolves the new list, or null if cancelled.
async function noteLinks(cur) {
  const list = cur.map(l => ({ ...l })), clients = await DB.all('SELECT id, first_name, last_name FROM clients ORDER BY last_name COLLATE NOCASE, first_name COLLATE NOCASE LIMIT 500');
  const books = await DB.all(`SELECT b.id, b.start_at, c.first_name, c.last_name FROM bookings b LEFT JOIN clients c ON c.id = b.client_id WHERE b.start_at >= date('now') ORDER BY b.start_at LIMIT 100`);
  const lab = (l) => l.label || NOTE_SECTIONS.find(s => s[0] === l.go)?.[1] || l.go;
  return new Promise((res) => { const o = document.createElement('div'); o.id = 'merge-dlg';
    const draw = () => { o.innerHTML = `<div class="card"><h2>Quick links</h2><div class="note-chips">${list.map((l, i) => `<button class="btn small" data-rm="${i}">${esc(lab(l))} ×</button>`).join('') || '<span class="muted">None yet.</span>'}</div>
      <div class="lbl">Section</div><select class="in" data-s><option value="">Add a section…</option>${NOTE_SECTIONS.map(([g, n]) => `<option value="${g}">${n}</option>`).join('')}</select>
      <div class="lbl">Client</div><select class="in" data-c><option value="">Add a client…</option>${clients.map(c => `<option value="${c.id}">${esc(fullName(c))}</option>`).join('')}</select>
      <div class="lbl">Appointment</div><select class="in" data-b><option value="">Add an upcoming appointment…</option>${books.map(b => `<option value="${b.id}">${esc(fmtDay(b.start_at))}${b.first_name ? ' · ' + esc(fullName(b)) : ''}</option>`).join('')}</select>
      <div class="lbl">Website</div><div class="row" style="gap:6px;flex-wrap:wrap"><input class="in" id="nl-url" type="url" inputmode="url" placeholder="example.com" autocomplete="off" style="flex:2 1 150px"><input class="in" id="nl-name" placeholder="Name (optional)" autocomplete="off" style="flex:1 1 110px"><button class="btn small" data-web>Add</button></div>
      <div class="row" style="gap:8px;margin-top:12px"><button class="btn" data-x style="flex:1">Cancel</button><button class="btn primary" data-ok style="flex:1">Done</button></div></div>`; };
    // A web address: https is assumed when none is typed, and only http(s) links are kept.
    const addWeb = () => { let s = $('#nl-url', o).value.trim(); if (!s) return false; if (!/^[a-z][a-z0-9+.-]*:/i.test(s)) s = 'https://' + s; let u; try { u = new URL(s); } catch { toast('That doesn’t look like a web address.'); return null; }
      if (!/^https?:$/.test(u.protocol) || !u.hostname.includes('.')) { toast('That doesn’t look like a web address.'); return null; }
      list.push({ type: 'web', url: u.href, label: $('#nl-name', o).value.trim() || u.hostname.replace(/^www\./, '') }); return true; };
    o.onchange = (e) => { const v = e.target.value, t = e.target; if (!v || t.id === 'nl-url' || t.id === 'nl-name') return;
      if (t.matches('[data-s]')) list.push({ type: 'section', go: v });
      if (t.matches('[data-c]')) { const c = clients.find(x => x.id === +v); list.push({ type: 'client', id: c.id, label: fullName(c) }); }
      if (t.matches('[data-b]')) { const b = books.find(x => x.id === +v); list.push({ type: 'booking', id: b.id, label: fmtDay(b.start_at) }); } draw(); };
    o.onclick = (e) => { const rm = e.target.closest('[data-rm]')?.dataset.rm; if (rm != null) { list.splice(+rm, 1); return draw(); }
      if (e.target.closest('[data-web]')) { if (addWeb()) draw(); return; }
      if (e.target.closest('[data-x]')) { o.remove(); res(null); } if (e.target.closest('[data-ok]')) { if (addWeb() === null) return; o.remove(); res(list); } };
    document.body.appendChild(o); draw(); }); }

/* Unsaved-form guard: navigating away from a dirty form asks first. */
const Dirty = {
  on: false,
  set(v) { this.on = v; },
  ok() { return !this.on || window.confirm('Discard unsaved changes?'); }
};
addEventListener('beforeunload', e => { if (Dirty.on) e.preventDefault(); });

/* ---------- Design workspaces ----------
   A workspace made only for design: the Studio's tools (design studio, stencil maker, bend tool, simulator, split,
   reel maker), forms, notes and the portfolio, without the tools for running a studio (clients, bookings, quotes,
   stats, stock, rules). Kept in the workspace (setting ws_mode, so backups carry it) and on its list entry; the
   body gets the class ws-design, which hides what is marked data-biz, and those pages lead home. */
const WS_BIZ = new Set(['rules-table', 'inventory-table', 'quotes-table', 'clients', 'clients-table', 'client', 'client-edit', 'book', 'bookings', 'booking-edit', 'quote', 'quote-cal', 'quotes', 'stats', 'inventory', 'inv-edit', 'stocktake', 'rules', 'rule-edit']);
const wsDesign = () => { try { return (Settings.get('ws_mode') || WS.cur?.mode) === 'design'; } catch { return WS.cur?.mode === 'design'; } };
/* ---------- Router ---------- */
const NAV_PARENT = { settings: 'more', client: 'clients', 'client-edit': 'clients', 'clients-table': 'clients', 'booking-edit': 'book', bookings: 'book',
  quote: 'more', 'quote-cal': 'more', 'quotes-table': 'more', 'stats-table': 'more', 'inventory-table': 'more', 'rules-table': 'more', stats: 'more', inventory: 'more', 'inv-edit': 'more', stocktake: 'more', rules: 'more', 'rule-edit': 'more', loyalty: 'more', pay: 'more',
  reel: 'studio', reels: 'studio', stencil: 'studio', sizes: 'studio', sketches: 'studio', tattoo: 'studio', portfolio: 'studio', pf: 'studio', 'pf-edit': 'studio',
  forms: 'studio', 'form-edit': 'studio', 'form-sign': 'studio', signed: 'studio' };
let currentHash = location.hash;
function render() {
  if (location.hash !== currentHash && !Dirty.ok()) { history.replaceState(null, '', currentHash || '#'); return; }
  Dirty.set(false);
  const dsg = wsDesign(); document.body.classList.toggle('ws-design', dsg);
  if (dsg && WS_BIZ.has((location.hash.slice(1) || 'home').split('/')[0])) { toast('Not in a design workspace. Change the workspace type in More › Settings.', 3500); location.replace('#home'); return; }
  currentHash = location.hash;
  const [key, arg] = (location.hash.slice(1) || 'home').split('/');
  if (R.playing && key !== 'reel') reelPause();
  const v = VIEWS[key] || VIEWS.home;
  $('#view-title').textContent = v.title(arg);
  const view = $('#view');
  document.body.classList.toggle('reel-full', key === 'reel');   /* the reel editor fills the screen */
  document.body.dataset.route = key;   /* lets the compact look leave the tattoo simulator as it is */
  view.innerHTML = v.render(arg);
  view.style.animation = 'none'; view.offsetHeight; view.style.animation = '';
  const active = NAV_PARENT[key] || key;
  document.querySelectorAll('.nav-btn').forEach(b => b.classList.toggle('active', b.dataset.view === active));
  $('#main').scrollTop = 0;
  Promise.resolve(v.mount?.(arg)).then(formCols, () => {});
  notesShow();
}
/* Entry forms on wide screens: the panels after the first go into two columns that each stack on their own, so a
   short panel never leaves a gap beside a tall one. The first half (by how much each holds) goes left, the rest
   right, so on a phone, where the columns are not drawn, the order stays as written. */
function formCols() {
  const f = $('#view form.card'); if (!f || f.classList.contains('pro') || !f.querySelector(':scope > .form-foot') || f.querySelector(':scope > .fcols')) return;
  const ps = [...f.querySelectorAll(':scope > .fsec')].slice(1); if (ps.length < 2) return;
  const w = ps.map(p => 1 + p.querySelectorAll('input:not([type=hidden]), textarea, select, .seg').length + p.querySelectorAll('textarea').length), half = w.reduce((a, b) => a + b, 0) / 2;
  let acc = 0, cut = ps.length - 1; for (let i = 0; i < ps.length; i++) { acc += w[i]; if (acc >= half) { cut = Math.min(ps.length - 1, Math.max(1, acc - w[i] / 2 > half ? i : i + 1)); break; } }
  const box = document.createElement('div'), L = document.createElement('div'), R = document.createElement('div'); box.className = 'fcols'; L.className = R.className = 'fcol';
  ps[0].before(box); box.append(L, R); ps.forEach((p, i) => (i < cut ? L : R).append(p));
}
$('#nav').addEventListener('click', e => {
  const b = e.target.closest('.nav-btn'); if (b) location.hash = b.dataset.view;
});
$('#view').addEventListener('click', e => {
  const t = e.target.closest('[data-go]'); if (t) location.hash = t.dataset.go;
});
/* ---------- One tab at a time ----------
   The database belongs to one tab (a Web Lock held by the database worker). A tab opened while
   another has it shows a card instead of waiting blind: Take over asks the other tab, over a
   BroadcastChannel, to let go. That tab stops its database worker, which frees the lock, and shows
   a card saying InkForge moved, with a button to take it back. A browser won't let one tab close
   another, so the old tab stays open but idle. */
const TabLock = {
  bc: 'BroadcastChannel' in self ? new BroadcastChannel('inkforge-tabs') : null,
  card(html) { let o = document.getElementById('tab-lock'); if (!o) { o = document.createElement('div'); o.id = 'tab-lock'; o.style.cssText = 'position:fixed;inset:0;z-index:300;display:grid;place-items:center;padding:16px;background:rgba(10,12,13,.92)'; document.body.appendChild(o); }
    o.innerHTML = `<div class="card" style="max-width:420px">${html}</div>`; return o; },
  async claim() {
    this.bc?.addEventListener('message', (e) => { if (e.data === 'takeover' && !this.gone) this.leave(); });
    if (!navigator.locks) return;
    // Our own worker asks for the lock as it starts. If the database answers, the lock is ours; if our request
    // is left waiting, another tab has it.
    let mine = false; const ready = DB.info().then(() => { mine = true; }, () => { mine = true; });
    for (let i = 0; i < 80 && !mine; i++) { let q = null; try { q = await navigator.locks.query(); } catch { return; }
      if (q.pending.some(l => l.name === 'inkforge-db')) break; await new Promise(r => setTimeout(r, 100)); }
    if (mine) return;
    await new Promise((done) => {
      const o = this.card(`<h2>Open in another tab</h2><p class="muted">InkForge can only run in one tab or window at a time, and it is open in another one right now.</p>
        <p class="muted" style="font-size:13px">Take over moves it here. Anything not yet saved in the other tab is lost, so finish up there first if you were in the middle of something.</p>
        <div class="row" style="gap:8px;margin-top:14px"><button class="btn primary" id="tl-take" style="flex:1">Take over</button></div>`);
      ready.then(() => { o.remove(); done(); });   // the other tab was closed instead
      o.querySelector('#tl-take').onclick = () => { this.bc?.postMessage('takeover');
        o.querySelector('.card').innerHTML = '<h2>Taking over…</h2><p class="muted">Waiting for the other tab to let go. If nothing happens, close the other tab yourself.</p>'; }; });
  },
  leave() { this.gone = true; booted = false; try { DB.release(); } catch {}
    this.card(`<h2>InkForge moved to another tab</h2><p class="muted">It is running in another tab or window now, so this one has stopped. You can close this tab.</p>
      <div class="row" style="gap:8px;margin-top:14px"><button class="btn primary" id="tl-back" style="flex:1">Use it here instead</button></div>`).querySelector('#tl-back').onclick = () => location.reload(); }
};
let booted = false;   // no view touches the database before boot has opened and migrated it
addEventListener('hashchange', () => { if (booted) render(); });

/* ---------- Boot ---------- */
(async () => {
  // A cached older index.html may not list newer files (e.g. tour.js). Load any that are missing now,
  // rather than failing when a workspace opens.
  for (const [src, have] of [['reel.js', () => typeof REEL_VERSION !== 'undefined'], ['design.js', () => typeof DESIGN_VERSION !== 'undefined'], ['tour.js', () => typeof TOUR_VERSION !== 'undefined']])
    if (!have()) await new Promise(res => { const sc = document.createElement('script'); sc.src = src + '?v=' + Date.now(); sc.onload = sc.onerror = res; document.head.appendChild(sc); });
  // reel.js and app.js ship together. If a cached older reel.js loaded next to this app.js,
  // refetch both past the browser cache and reload once (the flag stops a reload loop).
  if (typeof REEL_VERSION === 'undefined' || REEL_VERSION !== 10 || typeof DESIGN_VERSION === 'undefined' || DESIGN_VERSION !== 2 || typeof TOUR_VERSION === 'undefined' || TOUR_VERSION !== 1) {
    let tried = false; try { tried = sessionStorage.getItem('if-reload') === '1'; sessionStorage.setItem('if-reload', '1'); } catch {}
    if (!tried) { await Promise.all(['./', 'index.html', 'reel.js', 'design.js', 'tour.js', 'app.js', 'app.css', 'sw.js'].map(u => fetch(u, { cache: 'reload' }).catch(() => {}))); location.reload(); return; }
  }
  try { sessionStorage.removeItem('if-reload'); } catch {}
  /* The stylesheet carries the build number (--app-build at the end of app.css). A browser can keep an old app.css
     while the scripts come in new; if the numbers differ, load a fresh copy past the cache. */
  { const cssB = getComputedStyle(document.documentElement).getPropertyValue('--app-build').trim(), link = document.querySelector('link[rel="stylesheet"][href^="app.css"]');
    if (link && cssB !== String(APP_BUILD)) link.href = 'app.css?v=' + APP_BUILD + '-' + Date.now(); }
  if ('serviceWorker' in navigator && location.protocol !== 'file:') navigator.serviceWorker.register('sw.js');
  await TabLock.claim();
  try { await WS.load(); } catch (err) { console.error(err); }
  await storageProtect();
  let openId = '', forceStart = false;
  try { openId = sessionStorage.getItem('ws-open') || ''; forceStart = sessionStorage.getItem('ws-start') === '1';
    sessionStorage.removeItem('ws-open'); sessionStorage.removeItem('ws-start'); } catch {}
  const w = WS.get(openId) || (!forceStart && WS.auto && WS.get(WS.last));
  if (w) startWorkspace(w); else showStart();
})();

/* Ask the browser to keep this site's storage. Without it Android Chrome may clear all of it (every workspace and
   snapshot) when space runs low or after a crash. Installed apps are usually granted this without a prompt. */
let storageSafe = null;   // true, false, or null when the browser can't say
async function storageProtect() {
  if (!navigator.storage?.persist) return storageSafe;
  try { storageSafe = (await navigator.storage.persisted()) || (await navigator.storage.persist()); } catch {}
  return storageSafe;
}
const storageWarn = () => storageSafe === false ? `<div class="card start-warn" style="border-color:var(--red);margin-top:12px">
  <b>Storage not protected</b><p class="muted" style="margin:4px 0 8px;font-size:13px">This browser may clear everything stored here, every workspace included, when the device runs low on space.
  Installing InkForge to your home screen usually allows protection; Chrome and Edge allow it, Brave doesn\u2019t. Until then, save workspace files${GOOGLE_ON ? ' or keep workspaces in Google Drive' : ''}.</p>
  <button class="btn small" id="st-protect">Protect storage</button></div>` : '';

/* Where InkForge keeps its data, said the same way wherever storage comes up. */
const STORE_NOTE = `<b>Best in Chrome or Edge.</b> They give InkForge the most room (often many GB) and let it protect your data; some browsers, like Brave, Firefox and Safari, hold it to about 1\u20132 GB or won\u2019t protect it.
  The room you get also depends on how much free space the device has left, and it\u2019s shared by every workspace on this device (several artists on one tablet all use the same space).
  If it fills up, new photos, videos and changes can fail to save, and a browser that hasn\u2019t protected the storage may clear data to make room, so save a workspace file and free some space before it gets full.`;
/* Start screen: like a desktop app's welcome window. New, open a workspace file, or pick a recent one. */
function showStart() {
  const ago = (iso) => { if (!iso) return 'Never opened'; const d = (Date.now() - new Date(iso)) / 864e5;
    return d < 1 ? 'Opened today' : d < 2 ? 'Opened yesterday' : `Opened ${new Date(iso).toLocaleDateString()}`; };
  const draw = () => {
    const list = [...WS.list].sort((a, b) => (b.opened || '').localeCompare(a.opened || ''));
    o.innerHTML = `<div class="start-in">
      <div class="start-brand"><img src="icon.svg" alt=""><h1>InkForge</h1><span class="badge ea">Early Access</span><span class="start-build">Build ${APP_BUILD}</span></div>
      <div class="start-acts">
        <button class="start-big" id="st-new"><b>+ New workspace</b><span>Start fresh, e.g. for another artist</span></button>
        <label class="start-big"><b>Open file…</b><span>A workspace or backup file (.inkforge)</span><input type="file" accept=".inkforge,.sqlite,.db" hidden id="st-file"></label>
        ${GOOGLE_ON ? '<button class="start-big" id="st-drive"><b>☁ Link from Google Drive</b><span>A workspace you keep in your Drive, to use on this device too</span></button>' : ''}
      </div>
      <div class="row" style="align-items:center"><div class="letter" style="flex:1">Recent</div>
        <button class="btn small" id="st-saveall" data-tip="Save every workspace as a file in your Downloads folder">Save all</button></div>
      <div class="card list">${list.map(w => `<div class="c-row ws-row">
          <button class="c-main ws-open" data-ws="${w.id}"><span class="c-n">${w.cloud ? '<span class="ws-cloud" data-tip="Kept in Google Drive">☁</span> ' : ''}${esc(w.name)}${w.test ? ' <span class="ws-practice">practice</span>' : ''}${w.mode === 'design' ? ' <span class="ws-practice ws-dsg">design</span>' : ''}</span><span class="muted c-sub">${w.cloud ? 'Google Drive · ' : ''}${ago(w.opened)}</span></button>
          <button class="btn small icon-btn ${menu === w.id ? 'on' : ''}" data-wsmenu="${w.id}" aria-label="More">⋯</button>
          ${menu === w.id ? `<div class="row tpl-acts">
            <button class="btn small" data-wsren="${w.id}">Rename</button>
            <button class="btn small" data-wssave="${w.id}" data-tip="Save this workspace as a file to share or keep safe">Save file</button>
            ${w.cloud ? `<button class="btn small" data-wsunlink="${w.id}" data-tip="Keep using it on this device only. The copy in your Drive stays there.">Stop using Drive</button>`
              : w.test || !GOOGLE_ON ? '' : `<button class="btn small" data-wsup="${w.id}" data-tip="Keep this workspace in your Google Drive so your other devices can open it">Move to Google Drive</button>`}
            <button class="btn small danger" data-wsdel="${w.id}" style="margin-left:auto">Delete</button></div>` : ''}
        </div>`).join('')}</div>
      ${storageWarn()}
      ${AppInstall.card('start-inst')}
      <label class="toggle" style="display:inline-flex;margin-top:12px" data-tip="Skip this screen and go straight to the last workspace. Switch any time by tapping the workspace name at the top.">
        <input type="checkbox" id="st-auto" ${WS.auto ? 'checked' : ''}><span>Open my last workspace automatically</span></label>
      ${FS.can() ? `<label class="toggle" style="display:inline-flex;margin-top:8px" data-tip="Hide the browser's bars once a workspace opens. The full screen button at the top switches it back.">
        <input type="checkbox" id="st-fs" ${WS.fs !== false ? 'checked' : ''}><span>Go full screen when a workspace opens</span></label>` : ''}
      <p class="muted" style="font-size:12px;margin-top:16px">Workspaces are stored on this device. Save a workspace file to move it to another device or keep a copy safe: keeping that file safe is up to you.
        ${GOOGLE_ON ? 'Or keep a workspace in your own Google Drive (☁) to use it on several devices: one device edits at a time, the others can view or take over.' : ''}</p>
      <p class="muted store-note">${STORE_NOTE}</p>
    </div>`;
  };
  let menu = null;
  const o = document.createElement('div'); o.id = 'start';
  document.body.appendChild(o); draw();
  o.addEventListener('click', async (e) => {
    const t = e.target, id = (a) => t.closest(`[${a}]`)?.getAttribute(a);
    if (t.id === 'st-saveall') {
      // Plain downloads (not the share sheet) so the files land in Downloads; the browser may ask once to allow several.
      const stamp = new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-'); let n = 0;
      t.disabled = true; toast('Saving workspaces…');
      for (const w of WS.list) {
        try {
          const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([await buildBackup(w)], { type: 'application/octet-stream' }));
          a.download = `${w.name.replace(/[^\w-]+/g, '_')}-${stamp}.inkforge`; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 20000); n++;
          await new Promise(r => setTimeout(r, 400));
        } catch (err) { if (!/no data/.test(err.message)) toast(`Could not save "${w.name}": ${err.message}`, 5000); }   // never-opened ones have nothing to save
      }
      t.disabled = false; toast(n ? `${n} workspace file${n > 1 ? 's' : ''} saved to Downloads.` : 'No workspaces with data to save yet.', 4000); return;
    }
    if (t.id === 'st-protect') { await storageProtect(); toast(storageSafe ? 'Storage protected.' : 'The browser declined. Installing the app to your home screen usually allows it.', 5000); return draw(); }
    if (id('data-ws')) { o.remove(); return startWorkspace(WS.get(id('data-ws'))); }
    if (id('data-wsmenu')) { menu = menu === id('data-wsmenu') ? null : id('data-wsmenu'); return draw(); }
    const w = WS.get(id('data-wsren') || id('data-wssave') || id('data-wsdel') || id('data-wsup') || id('data-wsunlink'));
    if (w && id('data-wsup')) {
      if (!WS.gid && !(await cloudSetup())) return;
      if (!await ask(`Move "${w.name}" to your Google Drive?\n\nIt stays on this device too. Your other devices can then link to it from this screen.`)) return;
      toast('Uploading to Google Drive…', 60000);
      try { await Cloud.moveUp(w); toast(`"${w.name}" is now in your Google Drive.`); } catch (err) { toast('Could not upload: ' + (err.message === 'setup' ? 'Google Drive is not set up.' : err.message), 6000); }
      menu = null; return draw();
    }
    if (w && id('data-wsunlink')) {
      if (!await ask(`Stop using Google Drive for "${w.name}" on this device?\n\nThis device keeps its copy as a normal workspace. The copy in your Drive is left as it is.`)) return;
      if (w.cloud.lastHolder === Cloud.device().id) { try { await Cloud.auth(); await Cloud.setLock(w, false); } catch {} }
      delete w.cloud; await WS.save(); menu = null; return draw();
    }
    if (w && id('data-wsren')) { const n = await askText('Workspace name:', w.name); if (n?.trim()) { w.name = n.trim(); await WS.save(); draw(); } return; }
    if (w && id('data-wssave')) { try { await exportBackup(w); } catch (err) { toast('Could not save: ' + err.message, 5000); } return; }
    if (w && id('data-wsdel')) {
      if (!await ask(`Delete the workspace "${w.name}" and everything in it from this device?\n\nSave its file first if you might need it. This cannot be undone.`)) return;
      try { await WS.remove(w); toast('Workspace deleted.'); } catch (err) { toast(err.message, 5000); }
      if (!WS.list.length) await WS.create('My workspace');
      menu = null; return draw();
    }
    if (t.closest('#st-drive')) {
      if (!WS.gid && !(await cloudSetup())) return;
      let found;
      try { await Cloud.auth(); found = await Cloud.listWorkspaces(); } catch (err) { return toast(err.message === 'setup' ? 'Google Drive is not set up.' : 'Google Drive: ' + err.message, 6000); }
      const fresh = found.filter(f => !WS.list.some(x => x.cloud?.folder === f.id));
      if (!fresh.length) return toast(found.length ? 'All your Drive workspaces are already on this device.' : 'No InkForge workspaces in this Google Drive yet. Use "Move to Google Drive" on a workspace first.', 6000);
      const pick = fresh.length === 1 ? fresh[0] : await new Promise(res => {
        const d = document.createElement('div'); d.id = 'merge-dlg';
        d.innerHTML = `<div class="card"><h2>Workspaces in your Drive</h2>${fresh.map(f => `<button class="c-row" data-f="${f.id}" style="width:100%"><span class="c-main"><span class="c-n">☁ ${esc(f.name)}</span><span class="muted c-sub">Changed ${new Date(f.modifiedTime).toLocaleString()}</span></span></button>`).join('')}
          <button class="btn" data-f="" style="margin-top:10px">Cancel</button></div>`;
        d.onclick = (e) => { const b = e.target.closest('[data-f]'); if (b) { d.remove(); res(fresh.find(f => f.id === b.dataset.f)); } };
        document.body.appendChild(d);
      });
      if (!pick) return;
      try {
        const kids = await Cloud.names(pick.id);
        if (!kids.get('db.sqlite') || !kids.get('media')) return toast('That Drive folder is missing its files.', 5000);
        const nw = await WS.create(pick.name);
        nw.cloud = { folder: pick.id, db: kids.get('db.sqlite'), media: kids.get('media'), ver: null }; await WS.save();
        o.remove(); return startWorkspace(nw);
      } catch (err) { return toast('Google Drive: ' + err.message, 6000); }
    }
    if (t.closest('#st-new')) {
      const n = await askText('Name for the new workspace (e.g. the artist\'s name):', '');
      if (!n?.trim()) return;
      const mode = await new Promise((res) => { const d = document.createElement('div'); d.id = 'merge-dlg'; d.style.zIndex = 99;
        d.innerHTML = `<div class="card"><h2>What is it for?</h2><div class="dz-ex">
          <button data-wm="full"><b>Full studio</b><small>Clients, bookings, quotes, stats, stock and rules, with all the design tools too</small></button>
          <button data-wm="design"><b>Design only</b><small>Just the design side: design studio, stencil maker, bend tool, simulator, split, reel maker, forms, notes and portfolio</small></button></div>
          <p class="muted" style="font-size:12px;margin:8px 2px 0">You can change it later in More › Settings.</p><button class="btn" data-wm="" style="width:100%;margin-top:10px">Cancel</button></div>`;
        d.onclick = (e) => { const b = e.target.closest('[data-wm]'); if (!b && e.target !== d) return; d.remove(); res(b?.dataset.wm || null); }; document.body.appendChild(d); });
      if (!mode) return;
      const os = await DevOS.ask(); if (!os) return; DevOS.set(os);
      const nw = await WS.create(n.trim()); nw.fresh = true; if (mode === 'design') nw.mode = 'design'; await WS.save(); o.remove(); return startWorkspace(nw);
    }
  });
  o.addEventListener('change', async (e) => {
    if (e.target.id === 'st-auto') { WS.auto = e.target.checked; return WS.save(); }
    if (e.target.id === 'st-fs') { WS.fs = e.target.checked; return WS.save(); }
    if (e.target.id !== 'st-file') return;
    const f = e.target.files[0]; e.target.value = ''; if (!f) return;
    const bytes = new Uint8Array(await f.arrayBuffer());
    let name;
    try { name = parseBackup(bytes.slice()).name; } catch (err) { return toast(err.message, 5000); }
    name = name || f.name.replace(/(-\d{4}-\d\d-\d\d-\d\d-\d\d)?\.\w+$/, '').replace(/_/g, ' ');
    if (WS.list.some(w => w.name === name)) name += ' (opened)';
    const nw = await WS.create(name); o.remove();
    startWorkspace(nw, bytes);
  });
}

// Opens a workspace and runs the normal start-up (snapshot recovery, migrations, settings).
// `fileBytes`: a workspace/backup file to load into it first (from "Open file…").
/* Full screen when a workspace opens. Browsers allow it only straight after a tap, so it's asked for at once (picking
   a workspace is that tap); when the workspace opened by itself, the first tap in the app does it instead. */
function autoFullScreen() {
  if (WS.fs === false || !FS.can() || FS.on()) return;
  FS.set(true);
  const once = () => { removeEventListener('pointerup', once, true); if (!FS.on()) FS.set(true); };
  setTimeout(() => { if (!FS.on()) addEventListener('pointerup', once, true); }, 400);
}
async function startWorkspace(w, fileBytes) {
  autoFullScreen();
  const badge = $('#db-badge');
  let recovered = false, tourBack = false;
  try {
    await WS.open(w);
    if (w.cloud && !fileBytes) {
      if (!WS.gid && !(await cloudSetup())) return WS.switchTo(null);
      try { await Cloud.prepare(w); }
      catch (e) {
        if (e.message === 'cancel') return WS.switchTo(null);
        const mine = w.cloud.lastHolder === Cloud.device().id;
        toast('Google Drive: ' + e.message + (mine ? '' : '. Opened view only.'), 7000);
        Cloud.editing = mine; Cloud.viewOnly = !mine; Cloud.start(w);
      }
    }
    tourBack = !fileBytes && await Tour.recover();
    document.body.classList.toggle('practice', !!w.test);
    if (fileBytes) await restoreBackup(fileBytes);
    else if (!(await hasData())) {
      const snap = await Snapshot.load();
      if (snap) { await DB.importBytes(snap); recovered = true; }
    }
    await migrate();
    await Settings.load();
    if (!fileBytes && !(await WsPass.unlock(w))) { await Cloud.release?.(w); return WS.switchTo(null); }
    // Every table must belong to a merge section (or be marked device-only) in MERGE_TABLES,
    // otherwise "Merge from backup" would quietly leave its data behind.
    const unmapped = (await DB.all(`SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'`))
      .map(r => r.name).filter(t => !(t in MERGE_TABLES));
    if (unmapped.length) {
      console.error('Tables missing from MERGE_TABLES:', unmapped);
      if (location.hostname === 'localhost') toast('Developer: add ' + unmapped.join(', ') + ' to MERGE_TABLES.', 8000);
    }
    Cal.mode = Settings.get('cal_mode', innerWidth >= 900 ? 'week' : 'day');
    const info = await DB.info();
    // The badge names the open workspace; tapping it goes back to the start screen to switch.
    badge.textContent = (w.test ? 'PRACTICE · ' : '') + (w.cloud ? '☁ ' : '') + w.name;
    if (storageSafe === false && !w.cloud) setTimeout(() => toast('Storage is not protected: the browser could clear it. Protect it in Settings › Storage, or save a workspace file.', 6000), 1500);
    badge.className = 'badge ws-badge ' + (info.mode === 'opfs' ? 'ok' : 'warn');
    badge.dataset.tip = info.mode === 'opfs'
      ? w.cloud ? `Workspace "${w.name}" in Google Drive, ${Cloud.editing ? 'editing on this device' : 'view only on this device'}. Tap to switch workspace.`
        : `Workspace "${w.name}", saved on this device. Tap to switch workspace.`
      : 'This browser blocked on-device storage, so changes are lost on reload. Use https or localhost.';
    badge.onclick = () => { if (Dirty.ok()) { Dirty.set(false); Snapshot.save().then(() => Cloud.release(w)).finally(() => WS.switchTo(null)); } };
  } catch (err) {
    badge.textContent = 'DB error'; badge.className = 'badge warn'; badge.dataset.tip = err.message;
    console.error(err);
    // Block the UI rather than let anything be typed into a database that is not open.
    $('#view').innerHTML = `<div class="card alert"><h2>Can't open your data</h2><p>${esc(err.message)}</p>
      <button class="btn primary" onclick="location.reload()">Reload</button></div>`;
    return;
  }
  booted = true; notesShow();
  Snapshot.ready = true;
  render();
  if (w.cloud) cloudBar(Cloud.viewOnly ? undefined : null);
  if (tourBack) toast('The tour was interrupted; its examples have been removed.', 6000);
  if (w.test) {
    if (!w.seeded) { toast('Filling the practice workspace…', 20000);
      try { await Practice.seed(); w.seeded = true; await WS.save(); toast('Practice workspace ready. Try anything; it\'s all made up.', 6000); } catch (e) { console.error(e); toast('Could not fill the practice workspace: ' + e.message, 8000); }
      render(); }
    else { await Practice.refresh(); render(); }
  }
  if (w.mode && !Settings.get('ws_mode')) await Settings.set('ws_mode', w.mode);   /* the type chosen when it was made, kept in the workspace itself */
  if (w.fresh && wsDesign()) { delete w.fresh; await WS.save(); render(); }   /* a design workspace needs no hours or prices */
  if (w.fresh && Settings.get('setup_done') !== '1') runSetup();
  Practice.tidy().catch(() => {}); Tour.resume();
  if (recovered) toast('Your data was missing on start-up and has been restored from the last automatic save.', 8000);
  else if (fileBytes) { toast(`Opened "${w.name}".`); Snapshot.soon(); }
  else Snapshot.soon();
}

/* The on-screen keyboard over a window: when a text box in any pop-up window (anything fixed on screen) is
   focused and the keyboard would cover it, the window's card slides up just enough to show it (never off the top),
   and slides back when the keyboard closes or the focus leaves. One guard for every window in the app. */
(function kbGuard() {
  const vv = window.visualViewport; if (!vv) return;
  let cur = null;   /* { el, shift } */
  const reset = () => { if (cur) { cur.el.style.transform = cur.t; cur.el.style.transition = cur.tr; cur = null; } };
  const fit = () => {
    const a = document.activeElement;
    if (!a || !/^(INPUT|TEXTAREA)$/.test(a.tagName) || /^(range|checkbox|radio|color|file|button)$/.test(a.type)) return reset();
    let f = a; while (f && f !== document.body && getComputedStyle(f).position !== 'fixed') f = f.parentElement;
    if (!f || f === document.body) return reset();   /* not in a window: the page scrolls itself */
    const card = a.closest('.card, [role="dialog"]') || f, kb = innerHeight - (vv.height + vv.offsetTop);
    if (cur && cur.el !== card) reset();
    if (kb < 80) return reset();   /* no keyboard up */
    if (!cur) cur = { el: card, shift: 0, t: card.style.transform, tr: card.style.transition };
    const r = a.getBoundingClientRect(), cr = card.getBoundingClientRect(), bottom = vv.offsetTop + vv.height - 14;
    let shift = cur.shift + Math.max(0, r.bottom - bottom);
    shift = Math.min(shift, cur.shift + Math.max(0, cr.top - 8));   /* keep its top on screen */
    if (Math.abs(shift - cur.shift) < 1) return;
    cur.shift = shift; card.style.transition = 'transform .15s'; card.style.transform = shift ? `translateY(${-shift}px)` : cur.t;
  };
  vv.addEventListener('resize', () => requestAnimationFrame(fit));
  document.addEventListener('focusin', () => setTimeout(fit, 350));   /* after the keyboard has come up */
  document.addEventListener('focusout', () => setTimeout(() => { if (!document.activeElement || !/^(INPUT|TEXTAREA)$/.test(document.activeElement.tagName)) reset(); }, 100));
})();

/* Scrolled lists keep their place when they are redrawn. Many panels rebuild their HTML after a tap (tick a row, pick an
   item), which swaps a scrolled list for a new one at the top. This remembers where each scrolled box was (by its id, or
   its classes and a few parents), and when that box is replaced in the same moment by one just like it, scrolls the new
   one back to the same place. A box that simply closes is forgotten, so a window opened later starts at the top. */
(function keepScroll() {
  const last = new Map();
  const part = (e) => e.id ? '#' + CSS.escape(e.id) : e.tagName.toLowerCase() + [...e.classList].filter(c => !/^(on|open|sel|picked|active|drag|over)$/.test(c)).sort().map(c => '.' + CSS.escape(c)).join('');
  const sig = (el) => { const p = []; for (let e = el, i = 0; e && e !== document.body && i < 4; e = e.parentElement, i++) p.push(part(e)); return p.join('<'); };
  document.addEventListener('scroll', (ev) => { const el = ev.target; if (!(el instanceof Element) || el.id === 'main') return;
    if (el.scrollTop || el.scrollLeft) last.set(sig(el), { el, sel: part(el), top: el.scrollTop, left: el.scrollLeft }); else last.delete(sig(el)); }, true);
  new MutationObserver(() => { for (const [k, v] of last) { if (v.el.isConnected) continue; last.delete(k);
    for (const c of document.querySelectorAll(v.sel)) if (c !== v.el && !c.scrollTop && !c.scrollLeft && sig(c) === k) { c.scrollTop = v.top; c.scrollLeft = v.left; if (c.scrollTop || c.scrollLeft) last.set(k, { ...v, el: c }); break; } } })
    .observe(document.body, { childList: true, subtree: true });
})();

/* ---------- This device: Windows, Android or iPad ----------
   Some fixes only suit one kind of device, so they are switched on by the device picked here (kept on this device,
   not in the workspace, since one workspace can open on several). It starts as a guess from the browser.
   iPad (iOS): Safari treats a slow Apple Pencil stroke or a held pencil as "select this text" (a gap appears in the
   line and the page gets highlighted), and a downward pencil swipe drags the page out of full screen. In iPad mode
   nothing outside text boxes can be selected, there is no hold menu, and a pencil (or finger) stroke on a drawing
   surface never scrolls or swipes the page. Android and Windows are left as they are. */
const OS_LIST = [['windows', 'Windows'], ['android', 'Android'], ['ios', 'iPad']];
const DevOS = {
  guess() { const ua = navigator.userAgent; return /iPad|iPhone|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1) ? 'ios' : /Android/i.test(ua) ? 'android' : 'windows'; },
  get() { let v = null; try { v = localStorage.getItem('inkforge_os'); } catch {} return OS_LIST.some(x => x[0] === v) ? v : this.guess(); },
  set(v) { try { localStorage.setItem('inkforge_os', v); } catch {} this.apply(); },
  apply() { document.documentElement.dataset.os = this.get(); },
  /* Asked when a workspace is made: which device this is (the current choice first). */
  ask() { const cur = this.get(), g = this.guess();
    return new Promise((res) => { const d = document.createElement('div'); d.id = 'merge-dlg'; d.style.zIndex = 99;
      d.innerHTML = `<div class="card"><h2>Which device is this?</h2><div class="dz-ex">${[...OS_LIST].sort((a, b) => (b[0] === cur) - (a[0] === cur)).map(([v, n]) =>
        `<button data-os="${v}"><b>${n}${v === g ? ' <span class="muted" style="font-weight:400">(this looks like it)</span>' : ''}</b><small>${v === 'ios' ? 'iPad with Apple Pencil, in Safari' : v === 'android' ? 'Android tablet or phone, e.g. Samsung with S Pen' : 'Windows computer or tablet'}</small></button>`).join('')}</div>
        <p class="muted" style="font-size:12px;margin:8px 2px 0">It fits the pen and touch to the device. Change it any time in More › Settings.</p><button class="btn" data-os="" style="width:100%;margin-top:10px">Cancel</button></div>`;
      d.onclick = (e) => { const b = e.target.closest('[data-os]'); if (!b && e.target !== d) return; d.remove(); res(b?.dataset.os || null); }; document.body.appendChild(d); }); }
};
DevOS.apply();
(function iosPencil() {
  const ios = () => document.documentElement.dataset.os === 'ios';
  const editable = (el) => el?.closest?.('input, textarea, select, [contenteditable=""], [contenteditable="true"]');
  const drawing = (el) => el?.closest?.('canvas, .tt-stage, .dz-page, .dz-stage, #reel-cv, .st-view, .gv-stage, #fs-sig, .tt-pad, .tt-tpad');
  /* nothing but text boxes can be selected */
  document.addEventListener('selectstart', (e) => { if (ios() && !editable(e.target)) e.preventDefault(); });
  /* on a drawing surface: no hold menu or magnifier on touch-down, and no scroll or swipe-out while drawing */
  document.addEventListener('touchstart', (e) => { if (!ios() || !drawing(e.target) || editable(e.target)) return;
    if ([...e.touches].some(t => t.touchType === 'stylus')) e.preventDefault(); }, { passive: false });
  document.addEventListener('touchmove', (e) => { if (ios() && drawing(e.target) && !editable(e.target)) e.preventDefault(); }, { passive: false });
  document.addEventListener('contextmenu', (e) => { if (ios() && drawing(e.target)) e.preventDefault(); });
})();

/* ---------- A shortcut to InkForge: on the desktop, the home screen or the taskbar ----------
   Chrome and Edge (Windows, Android, ChromeOS, Mac) and Samsung Internet offer to install the app: the button opens
   that offer straight away. Safari (iPad, iPhone, Mac) and Firefox have no button a page can press, so the button
   shows the two or three taps to do it there. Once InkForge runs on its own (from the shortcut), the button says so. */
const AppInstall = {
  ev: null, done: false,
  standalone: () => matchMedia('(display-mode: standalone), (display-mode: fullscreen), (display-mode: minimal-ui)').matches || navigator.standalone === true,
  where() { const ua = navigator.userAgent, ios = /iPad|iPhone|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);
    return ios ? 'ios' : /Android/i.test(ua) ? (/Firefox/i.test(ua) ? 'android-ff' : 'android') : /Macintosh/.test(ua) && /Safari/.test(ua) && !/Chrome|Chromium|Edg/.test(ua) ? 'mac-safari' : /Firefox/i.test(ua) ? 'firefox' : 'desktop'; },
  card(cls) { const on = this.standalone() || this.done;
    return `<div class="card ${cls} app-inst"><div><b>Shortcut to InkForge</b><span class="muted">${on ? 'InkForge is installed: open it from its icon on your desktop or home screen.' : 'Put InkForge on your desktop, taskbar or home screen, to open it like an app in its own window. It also lets the browser protect its storage.'}</span></div>
      <button class="btn small ${on ? '' : 'primary'}" data-install ${on ? 'disabled' : ''}>${on ? 'Installed' : 'Make a shortcut'}</button></div>`; },
  async go() {
    if (this.standalone()) return toast('InkForge is already running from its shortcut.', 2500);
    if (this.ev) { const e = this.ev; this.ev = null; e.prompt(); const r = await e.userChoice.catch(() => null); if (r?.outcome === 'accepted') { this.done = true; toast('Done: InkForge is on your device. Open it from its icon.', 4000); this.refresh(); } return; }
    const w = this.where(), steps = {
      ios: ['Tap the Share button <b>⬆</b> (at the top on an iPad, the bottom on an iPhone).', 'Scroll down and tap <b>Add to Home Screen</b>.', 'Tap <b>Add</b>. InkForge opens full screen from its new icon.'],
      'mac-safari': ['In the menu bar, choose <b>File › Add to Dock</b> (or Share ⬆ › Add to Dock).', 'Click <b>Add</b>. InkForge then opens in its own window from the Dock.'],
      'android-ff': ['Tap the menu <b>⋮</b>.', 'Tap <b>Install</b> or <b>Add to Home screen</b>.'],
      android: ['Tap the browser menu <b>⋮</b>.', 'Tap <b>Install app</b> or <b>Add to Home screen</b>.', 'Tap <b>Install</b>.'],
      firefox: ['Firefox on a computer can\u2019t install web apps.', 'Open InkForge in <b>Chrome</b> or <b>Edge</b> and press this button there, or drag the address bar\u2019s lock icon onto the desktop for a plain shortcut.'],
      desktop: ['In the address bar, click the <b>install</b> icon (a screen with an arrow), or open the menu <b>⋮</b> › <b>Cast, save and share</b> › <b>Install page as app</b> (Edge: <b>Apps › Install this site as an app</b>).', 'Click <b>Install</b>. InkForge gets its own window and a desktop and Start menu shortcut.'] }[w];
    document.querySelectorAll('#merge-dlg').forEach(x => x.remove()); const o = document.createElement('div'); o.id = 'merge-dlg'; o.style.zIndex = 200;   /* above the start screen */
    o.innerHTML = `<div class="card" style="max-width:420px"><h2>Make a shortcut</h2>
      <p class="muted" style="margin-top:0">${w === 'ios' || w === 'mac-safari' ? 'Safari doesn\u2019t let a page add the shortcut itself, so it takes these taps:' : w === 'firefox' ? '' : 'This browser didn\u2019t offer the install straight away (it may need a moment, or InkForge is already installed). Do it from the browser:'}</p>
      <ol class="inst-steps">${steps.map(x => `<li>${x}</li>`).join('')}</ol>
      <button class="btn primary" data-ix style="width:100%;margin-top:10px">OK</button></div>`;
    o.onclick = (e) => { if (e.target === o || e.target.closest('[data-ix]')) o.remove(); }; document.body.appendChild(o); },
  refresh() { document.querySelectorAll('.app-inst').forEach(c => { const cls = [...c.classList].find(x => x !== 'card' && x !== 'app-inst') || ''; c.outerHTML = this.card(cls); }); }
};
addEventListener('beforeinstallprompt', (e) => { e.preventDefault(); AppInstall.ev = e; });   /* kept for the button, instead of the browser's own pop-up */
addEventListener('appinstalled', () => { AppInstall.done = true; AppInstall.ev = null; AppInstall.refresh(); });
document.addEventListener('click', (e) => { if (e.target.closest?.('[data-install]')) { e.preventDefault(); AppInstall.go(); } });

